const test = require('node:test');
const assert = require('node:assert/strict');
const { sortQueryEntries } = require('../src/query-order.cjs');

test("equal keys keep their incoming value order", () => {
  const pairs = [['zone', 'east'], ['site', 'zulu'], ['site', 'alpha'], ['area', 'north']];
  const before = pairs.map(pair => pair.slice());
  assert.deepEqual(sortQueryEntries(pairs), [['area', 'north'], ['site', 'zulu'], ['site', 'alpha'], ['zone', 'east']]);
  assert.deepEqual(pairs, before);
});

test("ordering follows UTF-16 rather than locale collation or code points", () => {
  assert.deepEqual(sortQueryEntries([['a', 'low'], ['Z', 'upper'], ['A', 'first']]), [['A', 'first'], ['Z', 'upper'], ['a', 'low']]);
  assert.deepEqual(sortQueryEntries([['\uE000', 'bmp'], ['\u{1F600}', 'astral']]), [['\u{1F600}', 'astral'], ['\uE000', 'bmp']]);
  assert.deepEqual(sortQueryEntries([]), []);
});

